    \geq \frac{2\kappa-\sqrt{(2\kappa')^2+\kappa^4}}{2\mu \gamma_2} 
    \stackrel{\eqref{eq:ODE_kappa}}{=} \frac{\kappa-\sqrt{\kappa^2-\mu}}{\mu\gamma_2}
    > 0.
  \end{align*}
  Similarly we get 
  \begin{align*}
    b_1a_1+b_2a_2
     &\hspace{-3mm}\stackrel{\eqref{eq:a1a2b1b2_1},\eqref{eq:a1a2b1b2_2}}{=}
      \frac{\gamma_1}{\gamma_2^2}\skp{\xi^1}{\xi^1} + \frac{1}{ \gamma_2}\skp{\xi^1}{\xi^3}  
     \stackrel{\eqref{eq:formulas_scpr_xi_1},\eqref{eq:formulas_scpr_xi_2}}{=}
       \gamma_1a_3^2  +  a_3(b_3-\gamma_1 a_3)  
      =  b_3a_3, \\
    -b_1a_2+b_2a_1
    &\hspace{-3mm}\stackrel{\eqref{eq:a1a2b1b2_1},\eqref{eq:a1a2b1b2_2}}{=}
      \frac{1}{\gamma_2}\skp{(\xi^1)^\perp}{\xi^3}  
    \stackrel{\eqref{eq:formulas_scpr_xi_3}}{=} \frac{a_3}{\sqrt\mu}.
  \end{align*}
  Combining these equations we obtain the formulas for $b_1,b_2$ and \eqref{eq:a_1a_2a_3b_1b_2b_3} is proved.

So let us first assume that $\gamma$ is an orbitlike elastica in $\mathbb{H}$ so that identity
     \eqref{eq:formula_Z} holds for all $s,s_0\in\mathbb{R}$ by Proposition~\ref{prop:formula_Z_orbitlike}.  We multiply \eqref{eq:formula_Z}
     with $2P_2\gamma_2(s)$ and obtain
     \begin{align*}
      (\gamma_1(s)-P_1)^2+\gamma_2(s)^2+P_2^2 
      = 2\gamma_2(s)\kappa(s)P_2\big( A W_1(s) + B  W_2(s) +  C \big) 
     \end{align*}
     where $A,B,C$ are given by the formulas \eqref{eq:formula_AB},\eqref{eq:def_C}.

To this end we introduce the matrices
  \begin{align*}
    \mathcal{W}:=\matII{W_1}{W_2}{W_1'}{W_2'},\qquad
    \mathcal{R}(\vartheta):=\matII{\cos(\vartheta)}{\sin(\vartheta)}{-\sin(\vartheta)}{\cos(\vartheta)}.
  \end{align*}
  Then Proposition~\ref{prop:properties_vartheta_orbitlike} gives the following:
    \begin{align*}
      \mathcal{W}
      &= 
      \matII{0}{\frac{\sqrt{\kappa^2-\mu}}{\kappa}}{\frac{-\sqrt{\mu}\kappa}{2\sqrt{\kappa^2-\mu}}}{
      \frac{\mu\kappa'}{\kappa^2\sqrt{\kappa^2-\mu}}} \mathcal{R}(\vartheta),\qquad
      \mathcal{W}^{-1}
      = 
      \mathcal{R}(-\vartheta)
      \matII{\frac{2\sqrt{\mu}\kappa'}{\kappa^2\sqrt{\kappa^2-\mu}}}{-\frac{2\sqrt{\kappa^2-\mu}}{\sqrt{\mu}\kappa}}
      {\frac{\kappa}{\sqrt{\kappa^2-\mu}}}{0}. \\
  \intertext{Combining this with \eqref{eq:formula_xi} and $(\kappa')^2=\kappa^2-\frac{1}{4}\kappa^4-\mu$ we get} 
     \xi^1




      &= 
      \mathcal{R}(-\vartheta)
      \vecII{\frac{1}{2\sqrt{\mu(\kappa^2-\mu)}}(2\kappa'\cos(\phi)+\kappa^2\sin(\phi))}{ 
      \frac{1}{2\mu\sqrt{\kappa^2-\mu}}(2\mu-2\kappa^2-2\kappa\kappa'\sin(\phi)+\kappa^3\cos(\phi))
      },  \\
      \xi^3




      &= 
      \mathcal{R}(-\vartheta)
      \vecII{\frac{1}{2\sqrt{\mu(\kappa^2-\mu)}}(2\kappa'\sin(\phi)-\kappa^2\cos(\phi))}{ 
      \frac{\kappa}{2\mu\sqrt{\kappa^2-\mu}}(\kappa^2\sin(\phi)+2\kappa'\cos(\phi))
      }.  
  \end{align*}

Writing $\skp{\cdot}{\cdot}$ for the standard inner product in $\mathbb{R}^2$ we get from 
  $(\kappa')^2=\kappa^2-\frac{\kappa^4}{4}-\mu$ and 
  the fact that the rotation matrices $\mathcal{R}(-\vartheta)$ are Euclidean isometries 
  \begin{align} 
    \skp{\xi^1}{\xi^1}
    &= \frac{(2\kappa'\cos(\phi)+\kappa^2\sin(\phi))^2}{4\mu (\kappa^2-\mu)}
      + \frac{(2\mu-2\kappa^2-2\kappa\kappa'\sin(\phi)+\kappa^3\cos(\phi))^2}{4\mu^2 (\kappa^2-\mu)}
      \notag    \\
    &= \frac{\cos^2(\phi)(\kappa^4+4\mu) +
    \sin^2(\phi)(4\kappa^2-\kappa^4) - 4\kappa^2\kappa'\sin(\phi)\cos(\phi)}{4\mu^2 }  \notag \\
    &\;+\frac{ 4\kappa^2-4\mu - 4\kappa^3 \cos(\phi)+8\kappa\kappa'\sin(\phi)}{4\mu^2} \notag \\
    &=
    \frac{(2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi))^2}{4\mu^2} \notag \\
    &\stackrel{\eqref{eq:b3a3_2}}{=}  a_3^2\gamma_2^2 . \\
    \intertext{Similar computations yield $((\xi^1)^\perp:=(-\xi^1_2,\xi^1_1))$}
    \skp{\xi^1}{\xi^3}
    &= \frac{\kappa^2\kappa'\cos^2(\phi)
      - 2 \kappa^2\kappa'\sin^2(\phi)
      + (\kappa^4-4(\kappa')^2)\sin(\phi)\cos(\phi)
    }{4\mu^2} \notag \\
    &\;+ \frac{-2\kappa^3\sin(\phi)
      - 4\kappa\kappa'\cos(\phi)
    }{4\mu^2} \notag \\
    &= -  \frac{(\kappa^2\sin(\phi)+2\kappa'\cos(\phi))
    (2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi))}{4\mu^2 } \notag \\
    &\stackrel{\eqref{eq:b3a3_1},\eqref{eq:b3a3_2}}{=}  a_3(b_3-\gamma_1 a_3), \\











    \skp{(\xi^1)^\perp}{\xi^3} 
    &= \frac{(2\mu-2\kappa^2-2\kappa\kappa'\sin(\phi)+\kappa^3\cos(\phi))
    (2\kappa'\sin(\phi)-\kappa^2\cos(\phi))
    }{ 4\mu^{3/2}(\kappa^2-\mu)} \notag \\
    &\;+
    \frac{(2\kappa'\cos(\phi)+\kappa^2\sin(\phi))(\kappa^3\sin(\phi)+2\kappa\kappa'\cos(\phi))
    }{4\mu^{3/2}(\kappa^2-\mu)} \notag \\
    &= \frac{2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi)}{2\mu^{3/2} (2-k^2)} \notag \\
    &\stackrel{\eqref{eq:b3a3_2}}{=} \frac{a_3\gamma_2}{\sqrt\mu}. \end{align}

This implies 
  \begin{align*}
    a_1^2+a_2^2
    \stackrel{\eqref{eq:a1a2b1b2_1}}{=} \frac{1}{\gamma_2^2}\skp{\xi^1}{\xi^1} 
   \stackrel{\eqref{eq:formulas_scpr_xi_1}}{=}   a_3^2.
  \end{align*}
  Hence, we find the formula for $a_3$ from \eqref{eq:a_1a_2a_3b_1b_2b_3} since  $a_3$ is positive due to
  \begin{align*}
    a_3
    \stackrel{\eqref{eq:b3a3_2}}{=} 
    \frac{2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi)}{2\mu \gamma_2} 
    \geq \frac{2\kappa-\sqrt{(2\kappa')^2+\kappa^4}}{2\mu \gamma_2} 
    \stackrel{\eqref{eq:ODE_kappa}}{=} \frac{\kappa-\sqrt{\kappa^2-\mu}}{\mu\gamma_2}
    > 0.
  \end{align*}

Similarly we get 
  \begin{align*}
    b_1a_1+b_2a_2
     &\hspace{-3mm}\stackrel{\eqref{eq:a1a2b1b2_1},\eqref{eq:a1a2b1b2_2}}{=}
      \frac{\gamma_1}{\gamma_2^2}\skp{\xi^1}{\xi^1} + \frac{1}{ \gamma_2}\skp{\xi^1}{\xi^3}  
     \stackrel{\eqref{eq:formulas_scpr_xi_1},\eqref{eq:formulas_scpr_xi_2}}{=}
       \gamma_1a_3^2  +  a_3(b_3-\gamma_1 a_3)  
      =  b_3a_3, \\
    -b_1a_2+b_2a_1
    &\hspace{-3mm}\stackrel{\eqref{eq:a1a2b1b2_1},\eqref{eq:a1a2b1b2_2}}{=}
      \frac{1}{\gamma_2}\skp{(\xi^1)^\perp}{\xi^3}  
    \stackrel{\eqref{eq:formulas_scpr_xi_3}}{=} \frac{a_3}{\sqrt\mu}.
  \end{align*}
  Combining these equations we obtain the formulas for $b_1,b_2$ and \eqref{eq:a_1a_2a_3b_1b_2b_3} is proved.

Now we prove the sufficiency of our conditions, so let $a_1,\ldots,b_3$ be given as in
     \eqref{eq:a_1a_2a_3b_1b_2b_3} we define $\gamma_1,\gamma_2$ by the formulas
     \eqref{eq:explicit_formula_orbitlike_1},\eqref{eq:explicit_formula_orbitlike_2}. Motivated 
     by the formulas~\eqref{eq:b3a3_1},\eqref{eq:b3a3_2}  derived in the ''only if''-part we define
     $\phi$ via
     \begin{equation} \vecII{\sin(\phi)}{\cos(\phi)}
         := \frac{\mu a_3}{2(\kappa^2-\mu)}\matII{\kappa^2}{2\kappa'}{2\kappa'}{-\kappa^2}
         \vecII{\gamma_1-\frac{b_3}{a_3}}{\gamma_2-\frac{\kappa}{\mu a_3}}. 
     \end{equation}

Then, choosing $P=(P_1,P_2)$ as in Proposition \ref{prop:choice_of_P} we obtain the inequalities
    \begin{align*}
      Z(s;P)
      &\leq -1 + \frac{\max \kappa}{\sqrt{\mu}} 
      \stackrel{\eqref{eq:def_kappa_orbitlike}}{=} 
      -1 + \frac{2}{\sqrt{2-k^2}\sqrt\mu}
      = -1 + \frac{\sqrt{2+2\sqrt{1-\mu}}}{\sqrt{\mu}}
      =:-1+\rho_1,   \\
      Z(s;P)
      &\geq -1 + \frac{\min \kappa}{\sqrt{\mu}} 
      \stackrel{\eqref{eq:def_kappa_orbitlike}}{=} 
      -1 + \frac{2\sqrt{1-k^2}}{\sqrt{2-k^2}\sqrt\mu}
      = -1 + \frac{\sqrt{2-2\sqrt{1-\mu}}}{\sqrt{\mu}}
      =: -1+\rho_2.
    \end{align*}

From Theorem~\ref{thm:explicit_formula_orbitlike} we get, using the notation from the proof of
    Theorem~\ref{thm:explicit_formula_orbitlike},
     \begin{align*}
        \eta
       &= \frac{bW+b_3}{aW+a_3}-\frac{b_3}{a_3} + i \Big( \frac{1}{\sqrt\mu (aW+a_3)} - \frac{1}{\sqrt\mu
       a_3} \Big) \\
       &= \frac{bWa_3 - b_3aW}{a_3(aW+a_3)} - i \frac{aW}{\sqrt\mu a_3(aW+a_3)} \\
       &\stackrel{\eqref{eq:a_1a_2a_3b_1b_2b_3}}{=}
         \frac{a^\perp W}{\sqrt\mu a_3(aW+a_3)} - i \frac{aW}{\sqrt\mu a_3(aW+a_3)} \\
       &\stackrel{\eqref{eq:def_theta}}{=} \frac{a_2\sin(\vartheta)+a_1\cos(\vartheta)}{N}
       + i\cdot \frac{a_1\sin(\vartheta)-a_2\cos(\vartheta)}{N}
     \end{align*}
     where $N:= \frac{\sqrt\mu\kappa}{\sqrt{\kappa^2-\mu}} a_3(aW+a_3)$ is a positive and
     $2n\sqrt{2-k^2}K(k)$-periodic function. Hence, we get from
     Proposition~\ref{prop:properties_vartheta_orbitlike}~(ii)  
     \begin{align*}
       \frac{1}{2\pi i} \int_0^{2n\sqrt{2-k^2}K(k)} \frac{\eta'(s)}{\eta(s)}\,ds 
       &= \frac{1}{2\pi i} \int_0^{2n\sqrt{2-k^2}K(k)} \big( - \frac{N'(s)}{N(s)} + i\vartheta'(s)\big) \,ds\\
       &= \frac{1}{2\pi} \big(\vartheta(2n\sqrt{2-k^2}K(k))-\vartheta(0)\big)  \\
       &=  \frac{n}{2\pi}  \Delta\theta_k, \\
       &=  m.
     \end{align*}

By $\mu_{k_{m,n}}=4(1-k_{m,n}^2)/(2-k_{m,n}^2)^2$ we observe that
    $\mu_{k_{m_n}}\to 1$ happens precisely when $k_{m_n}\to 0$ which, by Proposition~\ref{prop:rotation}
    and the definition of $k_{m,n}$, is equivalent to $2m_n/n\to \sqrt{2}$.

Assuming first that $\gamma$ is a wavelike elastica in $\mathbb{H}$ we get from
     Proposition~\ref{prop:formula_Z_wavelike}
     \begin{align*}
      (\gamma_1(s)-P_1)^2+\gamma_2(s)^2+P_2^2 
      = 2\gamma_2(s)P_2\big( A \hat W_1(s) + B  \hat W_2(s) +  C\kappa(s)\big) 
     \end{align*}
      for all $s\in\mathbb{R}$ and $A,B,C$ given by \eqref{eq:formula_AB},\eqref{eq:def_C}. As in the orbitlike case
      this leads to
     \begin{align*}
       1 = \gamma_2(s)\big(a_1 \hat W_1(s)+a_2\hat W_2(s)+a_3\kappa(s)\big),\quad
       \gamma_1(s) 
        &= \gamma_2(s)\big(b_1\hat W_1(s)+b_2\hat W_2(s)+b_3\kappa(s)\big)
     \end{align*}
     where the constants $a_1,a_2,a_3,b_1,b_2,b_3$ satisfy
     \eqref{eq:a1a2b1b2_1},\eqref{eq:a1a2b1b2_2},\eqref{eq:b3a3_1},\eqref{eq:b3a3_2} on $\mathbb{R}\setminus\{\kappa=0\}$.

To this end we introduce the matrices
  \begin{align*}
    \mathcal{W}:=\matII{W_1}{W_2}{W_1'}{W_2'},\qquad
    \mathcal{R}_h(\vartheta):=\matII{\cosh(\vartheta)}{-\sinh(\vartheta)}{-\sinh(\vartheta)}{\cosh(\vartheta)}.
  \end{align*}
  From Proposition~\ref{prop:properties_vartheta_wavelike} we get
    \begin{align*}
      \mathcal{W}
      &=  
      \matII{0}{\frac{\sqrt{\kappa^2-\mu}}{\kappa}}{-\frac{\sqrt{|\mu|}\kappa}{2\sqrt{\kappa^2-\mu}}}{\frac{\mu\kappa'}{\kappa^2\sqrt{\kappa^2-\mu}}}
      \mathcal{R}_h(\vartheta), \qquad
      \mathcal{W}^{-1}
      =  \mathcal{R}_h(-\vartheta)
      \matII{-\frac{2\sqrt{|\mu|}\kappa'}{\kappa^2\sqrt{\kappa^2-\mu}}}{-\frac{2\sqrt{\kappa^2-\mu}}{\sqrt{|\mu|}\kappa}}
      {\frac{\kappa}{\sqrt{\kappa^2-\mu}}}{0},  \\
    \intertext{and combining these formulas with the ones for $\xi^1,\xi^3$ from \eqref{eq:formula_xi} we get}
      \xi^1
      &=  \mathcal{R}_h(-\vartheta)
      \vecII{\frac{1}{2\sqrt{|\mu|(\kappa^2-\mu)}}(2\kappa'\cos(\phi)+\kappa^2\sin(\phi))}{
      \frac{1}{2\mu\sqrt{\kappa^2-\mu}}(2\mu-2\kappa^2-2\kappa\kappa'\sin(\phi)+\kappa^3\cos(\phi))
      },  \\
      \xi^3
      &=  \mathcal{R}_h(-\vartheta)
      \vecII{\frac{1}{2\sqrt{|\mu|(\kappa^2-\mu)}}(2\kappa'\sin(\phi)-\kappa^2\cos(\phi))}{
      \frac{\kappa}{2\mu\sqrt{\kappa^2-\mu}}(\kappa^2\sin(\phi)+2\kappa'\cos(\phi))
      }.
  \intertext{
  Writing $\skp{\cdot}{\cdot}_h$ for the inner product in $\mathbb{H}$ and $(w_1,w_2)^\perp=(w_2,w_1)$ we get from
  $(\kappa')^2=\kappa^2-\frac{\kappa^4}{4}-\mu$ and the fact that the rotation matrices
  $\mathcal{R}_h(\vartheta)$ are hyperbolic isometries}
  \skp{\xi^1}{\xi^1}_h
      &= -\frac{(2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi))^2 }{4\mu^2}
      = - a_3^2\gamma_2^2,\\
      \skp{\xi^1}{\xi^3}_h
      &=
      \frac{(\kappa^2\sin(\phi)+2\kappa'\cos(\phi))(2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi))}{4\mu^2}
      = \gamma_2 a_3(a_3\gamma_1-b_3),   \\
      \skp{(\xi^1)^\perp}{\xi^3}_h
      &= -\frac{2\kappa+2\kappa'\sin(\phi)-\kappa^2\cos(\phi)}{2\mu\sqrt{|\mu|}}
       = -\frac{a_3\gamma_2}{\sqrt{|\mu|}}.
  \end{align*}

In the case $a_3=0$ the above equations imply $a_2=|a_1|,b_1=\mathrm{sign}(a_1)b_2$ and 
  \eqref{eq:wavelike_b3a3_1},\eqref{eq:wavelike_b3a3_2} yield 
  \begin{align*}
    b_3^2
    &= \frac{(\kappa^2\sin(\phi)+2\kappa'\cos(\phi))^2}{4\mu^2}
    = \frac{\kappa^4+4(\kappa')^2-(2\kappa'\sin(\phi)-\kappa^2\cos(\phi))^2}{4\mu^2} \\
    &= \frac{\kappa^4+4(\kappa')^2-4\kappa^2}{4\mu^2}
    = \frac{1}{|\mu|}.
  \end{align*} 
  So \eqref{eq:wavelike_a_1a_2a_3b_1b_2b_3} is entirely proved.

Now let $a_1,\ldots,b_3$ be given as in \eqref{eq:wavelike_a_1a_2a_3b_1b_2b_3} and
  $\gamma=(\gamma_1,\gamma_2)$ the associated elastica. In analogy to 
  \eqref{eq:formula_phi} the angle function $\phi$ is defined via
     \begin{equation*} 
         \vecII{\sin(\phi)}{\cos(\phi)}
         := \frac{\mu}{2(\kappa^2-\mu)}\matII{\kappa^2}{2\kappa'}{2\kappa'}{-\kappa^2}
         \vecII{a_3\gamma_1- b_3}{a_3\gamma_2-\frac{\kappa}{\mu}},
     \end{equation*}
   Such a definition is possible because of 
   $\kappa^2((aW)^2-(a^\perp W)^2)= \kappa^2(a_1^2-a_2^2)(W_1^2-W_2^2)=(\kappa^2-\mu)a_3^2$
     \begin{align*}
       &\frac{\mu^2}{4(\kappa^2-\mu)^2} \Big(
       \Big( \kappa^2\big(a_3\gamma_1- b_3\big)+2\kappa'\big(a_3\gamma_2-\frac{\kappa}{\mu
       }\big)\Big)^2
       + \Big(
       2\kappa'\big(a_3\gamma_1- b_3\big)-2\kappa^2\big(a_3\gamma_2-\frac{\kappa}{\mu}\big)   \Big)^2   \Big) \\
       &= \frac{\big( \kappa|\mu|(a_3bW-b_3aW)\big)^2+ \big(-\kappa^2aW +
       (\mu-\kappa^2)a_3  \big)^2}{\kappa^2(\kappa^2-\mu)(aW+a_3)^2} \\
       &= \frac{ |\mu|\kappa^2(a^\perp W)^2
         + \kappa^4(aW)^2 +2\kappa^2(\kappa^2-\mu)a_3aW+ (\kappa^2-\mu)^2a_3^2
        }{\kappa^2(\kappa^2-\mu)(aW+a_3)^2} \\
       &= \frac{ \kappa^2\mu |a|_h^2|W|_h^2
         + (\kappa^4-\kappa^2\mu)(aW)^2 +2\kappa^2(\kappa^2-\mu)a_3aW+ (\kappa^2-\mu)^2a_3^2
        }{\kappa^2(\kappa^2-\mu)(aW+a_3)^2} \\
       &= \frac{(aW)^2 +2a_3aW+ a_3^2}{(aW+a_3)^2} \\
       &= 1.
     \end{align*}

Let $P=(P_1,P_2)$ be given as in Proposition \ref{prop:choice_of_P_wavelike}. By definition
    of $Z(\cdot;P)$ and $P_2^2=-|P_2|^2$ we find
    $(\gamma_1-P_1)^2+\gamma_2^2-|P_2|^2=2\gamma_2|P_2|\frac{\kappa}{\sqrt{|\mu|}}$ and thus
    \begin{align*}
      (\gamma_1-P_1)^2+(\gamma_2+\rho|P_2|)^2 &\geq |P_2|^2(1+\rho^2), \\
      (\gamma_1-P_1)^2+(\gamma_2-\rho|P_2|)^2 &\leq |P_2|^2(1+\rho^2),\\
      \text{where }\quad
      \rho:= \frac{\max |\kappa|}{\sqrt{|\mu|}}
      &= \frac{2k}{\sqrt{2k^2-1}\sqrt{|\mu|}} = \frac{\sqrt{2+2\sqrt{1-\mu}}}{\sqrt{|\mu|}}.
    \end{align*}

From the explicit formulas from Theorem \ref{thm:explicit_formula_wavelike} and
    Proposition~\ref{prop:W1W2_wavelike} we infer $\gamma_2(s) \to  0$ as $s\to \pm\infty$ and 
    \begin{align*}
      \lim_{s\to\pm\infty}
      \gamma_1(s) 
       \stackrel{\eqref{eq:explicit_formula_wavelike}}{=} 
        \lim_{s\to\pm\infty} \frac{b_1 \frac{\hat W_1(s)}{\hat W_2(s)}+b_2+b_3 \frac{\kappa(s)}{\hat W_2(s)}
         }{a_1    \frac{\hat W_1(s)}{\hat W_2(s)}+a_2+a_3 \frac{\kappa(s)}{\hat W_2(s)}} 
         = \frac{\mp b_1 +b_2}{\mp a_1 +a_2} 
       \stackrel{\eqref{eq:wavelike_a_1a_2a_3b_1b_2b_3}}{=} 
         \frac{b_3}{a_3} \pm \frac{1}{\sqrt{|\mu|} a_3}.
    \end{align*}

These equations imply \eqref{eq:DirProblem_choice_a3},\eqref{eq:DirProblem_choice_b3} as well as
    \begin{align}
      \matII{\cos(\phi_A)}{-\sin(\phi_A)}{\sin(\phi_A)}{\cos(\phi_A)}\vecII{\kappa(0)^2}{2\kappa'(0)}
      &= \vecII{2\kappa(0)-2\mu A_2 a_3}{2\mu(a_3A_1-b_3)}, \\
      \matII{\cos(\phi_B)}{-\sin(\phi_B)}{\sin(\phi_B)}{\cos(\phi_B)}\vecII{\kappa(L)^2}{2\kappa'(L)}
      &= \vecII{2\kappa(L)-2\mu B_2 a_3}{2\mu(a_3B_1-b_3)}. \end{align}

Taking the modulus on each side and using $\kappa^4+4(\kappa')^2=4(\kappa^2-\mu)$ we find
    that the quadratic term $4\kappa(0)^2,4\kappa(L)^2$ cancels and we get
    \begin{align}
       \kappa(0) &= \frac{1+\mu(a_3^2A_2^2+(a_3A_1-b_3)^2)}{2A_2a_3}, \\
       \kappa(L) &= \frac{1+\mu(a_3^2B_2^2+(a_3B_1-b_3)^2)}{2B_2a_3}. \end{align}

From $\gamma(0)=(A_1,A_2)$ and $\gamma(L)=(B_1,B_2)$ and the explicit formulas for $\gamma_1,\gamma_2$ from
   Theorem~\ref{thm:explicit_formula_orbitlike} and in particular the relation
   $b=\frac{b_3}{a_3}a+\frac{1}{\sqrt\mu a_3}a^\perp$ from \eqref{eq:a_1a_2a_3b_1b_2b_3} imply 
   \begin{align*}
     \matII{a_1}{a_2}{-a_2}{a_1}\vecII{W_1(0)}{W_2(0)}
     =
     \frac{1}{A_2\kappa(0)}  \vecII{\sigma_1}{\sigma_2}, \qquad
     \matII{a_1}{a_2}{-a_2}{a_1}\vecII{W_1(L)}{W_2(L)}
     = \frac{1}{B_2\kappa(L)}\vecII{\sigma_3}{\sigma_4}.
   \end{align*}
   Notice that we used here $\sigma_1=1-a_3A_2\kappa(0),\sigma_2=1-a_3A_2\kappa(L)$, see
   \eqref{eq:sigmas} and \eqref{eq:DirProblem_Formula2a},\eqref{eq:DirProblem_Formula2b}.
   Using $a_1^2+a_2^2=a_3^2$ from~\eqref{eq:a_1a_2a_3b_1b_2b_3} we may solve this linear problem and arrive at
   \begin{align} \vecII{W_1(0)}{W_2(0)}
	= \frac{1}{a_3^2A_2\kappa(0)}\vecII{ a_1\sigma_1 - a_2\sigma_2}{ a_2\sigma_1 + a_1\sigma_2},
	\qquad
      \vecII{W_1(L)}{W_2(L)}
      = \frac{1}{a_3^2B_2\kappa(L)}  \vecII{ a_1\sigma_3 - a_2\sigma_4}{ a_2\sigma_3 + a_1\sigma_4}.
    \end{align}

From \eqref{eq:DirProblem_W_2W_1} and \eqref{eq:DirProblem_equationsforW_1W_2} we get
   \begin{align*}
     e^{i\vartheta(0)}
     =  \frac{a_2\sigma_1+a_1\sigma_2+i(a_2\sigma_2-a_1\sigma_1)}{
     \sqrt{(a_1^2+a_2^2)(\sigma_1^2+\sigma_2^2)}},   \qquad
     e^{i\vartheta(L)}
     =  \frac{a_2\sigma_3+a_1\sigma_4+i(a_2\sigma_4-a_1\sigma_3)}{
     \sqrt{(a_1^2+a_2^2)(\sigma_3^2+\sigma_4^2)}}.   
   \end{align*}
   The first equation and $a_1^2+a_2^2=a_3^2$ imply \eqref{eq:DirProblem_choice_a1a2}. Dividing 
   both equations we finally end up with \eqref{Gl:DirProblem_II}. This finishes the ''only if''-part of our
   statement.

This entails 
    \begin{align} \begin{aligned}
      &\;aW(0)+ia^\perp W(0) \\
      &= (W_2(0)-iW_1(0))(a_2+ia_1) \\
      &\stackrel{\eqref{eq:def_theta},\eqref{eq:DirProblem_choice_a1a2}}{=} 
        \frac{\sqrt{\kappa(0)^2-\mu}}{\kappa(0)}e^{i\vartheta(0)}\cdot  a_3
        \frac{\sigma_1+i\sigma_2}{\sqrt{\sigma_1^2+\sigma_2^2}}e^{-i\vartheta(0)}   \\
      &\stackrel{\eqref{eq:sigma12_sq}}{=} \frac{\sigma_1+i\sigma_2}{\kappa(0)A_2}. 
      \end{aligned}
    \end{align}
    From this identity and  
    $\sigma_1=1-a_3A_2\kappa(0),\sigma_2= \sqrt\mu (A_1a_3-b_3)$ we deduce  
    \begin{align*}
       \gamma_2(0)
      &\stackrel{\eqref{eq:explicit_formula_orbitlike_2}}{=} \frac{1}{\kappa(0)(aW(0)+a_3)}
      = \frac{1}{\kappa(0)(\frac{\sigma_1}{\kappa(0)A_2}+a_3)} 
      = A_2, \\
      \gamma_1(0) 
      &\stackrel{\eqref{eq:explicit_formula_orbitlike_1}}{=} \frac{bW(0)+b_3}{aW(0)+a_3} \\ 
      &= A_2\kappa(0)(bW(0)+b_3) \\
      &\stackrel{\eqref{eq:DirProblem_choice_b1b2}}{=} 
        A_2\kappa(0) \Big( \frac{b_3}{a_3} aW(0)+ \frac{1}{\sqrt\mu a_3}
      a^\perp W(0)+b_3\Big) \\
      &\stackrel{\eqref{eq:aW(0)}}{=} \frac{b_3}{a_3} \sigma_1 + \frac{1}{\sqrt\mu a_3} \sigma_2 +
      b_3A_2\kappa(0)  \\
      &= A_1.
    \end{align*}

The same way we find $\sigma_3^2+\sigma_4^2 = (\kappa(L)^2-\mu)B_2^2a_3^2$ and deduce
    \begin{align*}
      aW(L)+ia^\perp W(L) 
      &= (a_2+ia_1)(W_2(L)-iW_1(L)) \\
      &\stackrel{\eqref{eq:DirProblem_W_2W_1}}{=} (a_2+ia_1)(W_2(0)-iW_1(0))
      \frac{\kappa(0)\sqrt{\kappa(L)^2-\mu}}{\kappa(L)\sqrt{\kappa(0)^2-\mu}} e^{i(\vartheta(L)-\vartheta(0))} \\
      &\stackrel{\eqref{Gl:DirProblem_II}}{=} \big(aW(0)+ia^\perp W(0)\big)
      \frac{\kappa(0)\sqrt{\kappa(L)^2-\mu}}{\sqrt{\kappa(0)^2-\mu}\kappa(L)}
      \frac{(\sigma_1-i\sigma_2)(\sigma_3+i\sigma_4)}{\sqrt{\sigma_1^2+\sigma_2^2}\sqrt{\sigma_3^2+\sigma_4^2}}
      \\
      &\stackrel{\eqref{eq:aW(0)}}{=} 
      \frac{\sqrt{\kappa(L)^2-\mu}(\sigma_1+i\sigma_2)}{A_2\kappa(L)\sqrt{\kappa(0)^2-\mu}}
      \frac{(\sigma_1-i\sigma_2)(\sigma_3+i\sigma_4)}{\sqrt{\sigma_1^2+\sigma_2^2}\sqrt{\sigma_3^2+\sigma_4^2}}
      \\
      &=   \frac{\sqrt{\kappa(L)^2-\mu}}{A_2\kappa(L)\sqrt{\kappa(0)^2-\mu}}
      \frac{\sqrt{\sigma_1^2+\sigma_2^2}(\sigma_3+i\sigma_4)}{\sqrt{\sigma_3^2+\sigma_4^2}}   \\
      &\stackrel{\eqref{eq:sigma12_sq}}{=}   \frac{\sigma_3+i\sigma_4}{B_2\kappa(L)}.
    \end{align*}
    As above we deduce $\gamma_1(L)=B_1,\gamma_2(L)=B_2$ so that it remains to show
    $e^{i\phi(0)}=e^{i\phi_A},e^{i\phi(L)}=e^{i\phi_B}$.

In particular, $\kappa$ is symmetric about $\tfrac{L}{2}$ and our next aim is to show
    $\gamma_1(\tfrac{L}{2})=\sin(\phi(\tfrac{L}{2}))=0$. To this end we notice that \eqref{Gl:DirProblem_II}
    implies 
    \begin{equation} e^{i(\vartheta(L)-\vartheta(0))} 
      = \frac{(\sigma_1-i\sigma_2)^2}{\sigma_1^2+\sigma_2^2}, \quad\text{hence }
      \frac{\sigma_1-i\sigma_2}{\sqrt{\sigma_1^2+\sigma_2^2}}
      = \pm e^{i(\vartheta(L)-\vartheta(0))/2}
      = \pm e^{i(\vartheta(L/2)-\vartheta(0))}.
    \end{equation}
    Indeed, the formula for $L$ and Proposition~\ref{prop:properties_vartheta_orbitlike} imply
    $$
      \vartheta(L)-\vartheta(0)
       = \vartheta(-2s_*)+l\Delta\theta_k-\vartheta(0) 
       = (l-1)\Delta\theta_k-2\vartheta(0) 
      = 2  \big( \vartheta(\tfrac{L}{2}) -\vartheta(0)\big).
    $$

Additionally, by the choice of $a_1,a_2$ from~\eqref{eq:DirProblem_choice_a1a2} we get
    \begin{align*}
      a^\perp W(\tfrac{L}{2})
      &= \Re\Big( (a_1+ia_2)\overline{(W_2+iW_1)(\tfrac{L}{2})}\Big) \\
      &= a_3
      \Re\Big(
      \frac{\sigma_2+i\sigma_1}{\sqrt{\sigma_1^2+\sigma_2^2}}e^{i\vartheta(0)}\cdot
      \frac{\sqrt{\kappa(\tfrac{L}{2})^2-\mu}}{\kappa(\tfrac{L}{2})} 
       e^{i(-\vartheta(L/2)))} \Big)  \\
      &\stackrel{\eqref{eq:cor:angle_condition}}{=} \frac{ a_3\sqrt{\kappa(\tfrac{L}{2})^2-\mu}}{\kappa(\tfrac{L}{2})}
      \Re\big( \pm i e^{i\vartheta(L/2))}e^{-i\vartheta(L/2))} \big) \\
      &= 0.
    \end{align*}

Moreover, the formulas
    \eqref{eq:DirProblem_Formula2a},\eqref{eq:DirProblem_Formula2b},\eqref{eq:DirProblem_Formula4a},\eqref{eq:DirProblem_Formula4b}
    imply $\kappa(0)=\kappa(L),\kappa'(0)=\kappa'(L)$ and thus $L=2n\sqrt{2-k^2}K(k)$ for some $n\in\mathbb{N}$.

By Jacobi's imaginary transformation (see 161.01 in \cite{ByrFri_handbook}) we have  
    $$
      \mathrm{dn}(i\alpha,k)^2 
      = \frac{\mathrm{dn}^2(\alpha,k')}{\mathrm{cn}^2(\alpha,k')}
      \stackrel{\eqref{eq:Jacobi_trigonometric_identities}}{=}
      \frac{1-(k')^2\mathrm{sn}^2(\alpha,k')}{1-\mathrm{sn}^2(\alpha,k')} 
      = 1 + \frac{k^2\mathrm{sn}^2(\alpha,k')}{1-\mathrm{sn}^2(\alpha,k')} \qquad (k':=\sqrt{1-k^2})
    $$
    so that one possible choice is $\alpha=\alpha_k$ where 

    $\mathrm{sn}(\alpha_k,k')=k'$, i.e. $\alpha_k:=F(k',k')$, see \eqref{eq:Jac_Inverse}.

Differentiating (ii) and
    using \eqref{eq:Jacobi_ODE_1terOrdnung},\eqref{eq:Jacobi_ODE_2terOrdnung}
    we get (iii) and (iv).

We now prove (vi) and (vii). Using 1051.04 in \cite{ByrFri_handbook} we get 
     \begin{align*}
       w_+(s+2lK(k))
       &= \frac{H(s+2lK(k)-i\alpha_k,k)}{\Theta(s+2lK(k),k)}e^{(s+2lK(k))\zeta(i\alpha_k,k)} \\
       &= \frac{(-1)^l H(s-i\alpha_k,k)}{\Theta(s,k)}e^{s\zeta(i\alpha_k,k)} e^{2lK(k)\zeta(i\alpha_k,k)}
       \\
       &= w_+(s) e^{l(2K(k)\zeta(i\alpha_k,k)+\pi i)}. 
     \end{align*}

Finally, we have
    \begin{align*}
      (w_1+iw_2)(-K(k)) 
      \stackrel{\eqref{eq:Hermite_Halphen}}{=} 
        e^{-K(k)\zeta(i\alpha_k,k)} 

      =  e^{i(\pi-\Delta\theta_k)/2} 
    \end{align*}  
    because of $(w_1^2+w_2^2)(-K(k))=1$ by Proposition~\ref{prop:w1w2_orbitlike}~(ii) and because 
    $H(-K(k)-i\alpha_k,k)$, $\Theta(-K(k),k)$ are real and positive for all $k\in (0,1)$ by
    \eqref{eq:JacobianTheta_series}.

For the proof we set $z:=-K(k)+ \frac{s+s_*}{\sqrt{2-k^2}}$ so that
      \eqref{eq:def_kappa_orbitlike},\eqref{eq:def_Wj} give
     \begin{align} \begin{aligned}
       w_j(z)= \sqrt{2-k^2}W_j(s),&\quad w_j'(z)= (2-k^2)W_j'(s) \quad (j=1,2)\\
       \kappa(s) &= \frac{2}{\sqrt{2-k^2}}\mathrm{dn}(z+K(k),k),\\
       \kappa'(s) &= -\frac{2k^2}{2-k^2}\mathrm{sn}(z+K(k),k)\mathrm{cn}(z+K(k),k).
       \end{aligned}
     \end{align}

Using the identities from \eqref{eq:Jac_Additionstheoreme} we get
     \begin{align} \begin{aligned}
       \mathrm{dn}(z,k)
       &= \frac{\sqrt{1-k^2}}{\mathrm{dn}(z+K(k),k)}
       \stackrel{\eqref{eq:formulas_z_vs_s}}{=}  \frac{2\sqrt{1-k^2}}{\sqrt{2-k^2}} \frac{1}{\kappa(s)}, \\
       \mathrm{sn}(z,k)\mathrm{cn}(z,k)
       &= -  \frac{\sqrt{1-k^2} \mathrm{sn}(z+K(k),k)\mathrm{cn}(z+K(k),k)}{\mathrm{dn}^2(z+K(k),k)}
       \stackrel{\eqref{eq:formulas_z_vs_s}}{=} \frac{2\sqrt{1-k^2}}{k^2} \frac{\kappa'(s)}{\kappa(s)^2}.
       \end{aligned}
     \end{align}

Now we exploit \eqref{eq:formulas_z_vs_s},\eqref{eq:formulas_dnsncn} and
     Proposition~\ref{prop:w1w2_orbitlike} in order to prove (i)-(vi).
     The first item follows from 
     \begin{align*}
       W_1(s)^2+W_2(s)^2
       &\stackrel{\eqref{eq:formulas_z_vs_s}}{=} \frac{w_1(z)^2+w_2(z)^2}{2-k^2}
       \stackrel{\ref{prop:w1w2_orbitlike}.(ii)}{=} 1-\frac{\mathrm{dn}^2(z,k)}{2-k^2}

       \stackrel{\eqref{eq:formulas_dnsncn}}{=}
       \frac{\kappa(s)^2-\mu}{\kappa(s)^2}. \\
     \intertext{The assertion (ii) is true because of}
       W_1'(s)
       &\stackrel{\eqref{eq:formulas_z_vs_s}}{=} \frac{1}{2-k^2} w_1'(z) \\
       &= \frac{1}{2-k^2}
       \frac{w_1(z)(w_1w_1'+w_2w_2')(z)-w_2(z)(w_1w_2'-w_2w_1')(z)}{(w_1^2+w_2^2)(z)} \\
       &\hspace{-1.2cm}\stackrel{\ref{prop:w1w2_orbitlike}.(ii)-(iv)}{=} \frac{1}{(2-k^2)^{3/2}}
         \frac{k^2\mathrm{dn}(z,k)\mathrm{cn}(z,k)\mathrm{sn}(z,k) W_1(s)- \sqrt{1-k^2}\sqrt{2-k^2}W_2(s)}{W_1(s)^2+W_2(s)^2}
         \\
      &\stackrel{\eqref{eq:formulas_dnsncn}}{=}\frac{4(1-k^2)}{(2-k^2)^2} \frac{\kappa'(s)}{\kappa(s)^3}
      \frac{W_1(s)}{W_1(s)^2+W_2(s)^2} - \frac{\sqrt{1-k^2}}{2-k^2} \frac{W_2(s)}{W_1(s)^2+W_2(s)^2}  \\
      &\stackrel{\ref{prop:W1W2_orbitlike}.(i)}{=} \frac{\mu\kappa'(s)}{\kappa(s)(\kappa(s)^2-\mu)} W_1(s)
      - \frac{\sqrt\mu \kappa(s)^2}{2(\kappa(s)^2-\mu)}W_2(s). \\
     \intertext{Similarly, (iii) follows from}
       W_2'(s)
       &= \frac{1}{2-k^2}
       \frac{w_2(z)(w_1w_1'+w_2w_2')(z)+w_1(z)(w_1w_2'-w_2w_1')(z)}{(w_1^2+w_2^2)(z)} \\
       &= \frac{\sqrt\mu \kappa(s)^2}{2(\kappa(s)^2-\mu)}W_1(s) +
       \frac{\mu\kappa'(s)}{\kappa(s)(\kappa(s)^2-\mu)} W_2(s). \\
     \intertext{









     The items (iv),(v) follow directly from
     Proposition~\ref{prop:w1w2_orbitlike}~(iv),(v).
     Finally, we set $t:= -s-2s_*+2l\sqrt{2-k^2}K(k)$ so that (vi) results from}
     W_1(s)+iW_2(s)
     &= (w_1+iw_2) \big( -K(k)+\frac{-(t+s_*)+2l\sqrt{2-k^2}K(k)}{\sqrt{2-k^2}} \big) \\
     &= (w_1+iw_2) \big( K(k)-\frac{t+s_*}{\sqrt{2-k^2}} + (2l-2)K(k)\big) \\
     &\stackrel{\ref{prop:w1w2_orbitlike}.(vi)}{=}  (w_1+iw_2)
     \big(K(k)-\frac{t+s_*}{\sqrt{2-k^2}}\big) e^{i(l-1)\Delta\theta_k}  \\
     &\stackrel{\ref{prop:w1w2_orbitlike}.(i)}{=} (-w_1+iw_2) \big(-K(k)+\frac{t+s_*}{\sqrt{2-k^2}}\big)
     e^{i(l-1)\Delta\theta_k}  \\
     &= (-W_1(t)+iW_2(t))  e^{i(l-1)\Delta\theta_k}.
   \end{align*}

Next we prove the assertions from Proposition~\ref{prop:properties_vartheta_orbitlike}, namely  
    $$
      \vartheta' = \frac{\sqrt\mu \kappa^2}{2(\kappa^2-\mu)},\qquad
       \matII{W_1}{W_2}{W_1'}{W_2'}
      =  
      \matII{0}{\frac{\sqrt{\kappa^2-\mu}}{\kappa}}{\frac{-\sqrt{\mu}\kappa}{2\sqrt{\kappa^2-\mu}}}{
      \frac{\mu\kappa'}{\kappa^2\sqrt{\kappa^2-\mu}}}
      \matII{\cos(\vartheta)}{\sin(\vartheta)}{-\sin(\vartheta)}{\cos(\vartheta)}
    $$
    as well as 
    \begin{itemize}
	  \item[(i)] $\vartheta(-s_*+l\sqrt{2-k^2}K(k)) = \frac{l-1}{2}\Delta\theta_k$,
      \item[(ii)] $\vartheta(s+2l\sqrt{2-k^2}K(k))-\vartheta(s) = l\Delta\theta_k$,
      \item[(iii)] $\vartheta(-s_*+s)+\vartheta(-s_*-s) = -\Delta\theta_k$.
    \end{itemize}

Differentiating both sides and using Proposition~\ref{prop:W1W2_orbitlike}~(ii),(iii) we arrive at
    \begin{align*}
      &-c(s)\vartheta'(s) \vecII{\cos(\vartheta(s))}{\sin(\vartheta(s))}
      + c'(s) \vecII{-\sin(\vartheta(s))}{\cos(\vartheta(s))} \quad
      =\quad \vecII{W_1'(s)}{W_2'(s)} \\
      &= \frac{\mu\kappa'(s)}{\kappa(s)(\kappa(s)^2-\mu)} \vecII{W_1(s)}{W_2(s)}
      + \frac{\sqrt\mu\kappa(s)^2}{2(\kappa(s)^2-\mu)} \vecII{-W_2(s)}{W_1(s)}   \\
      &= \frac{\mu\kappa'(s)c(s)}{\kappa(s)(\kappa(s)^2-\mu)} \vecII{-\sin(\vartheta(s))}{\cos(\vartheta(s))}
      - \frac{\sqrt\mu\kappa(s)^2c(s)}{2(\kappa(s)^2-\mu)} \vecII{\cos(\vartheta(s))}{\sin(\vartheta(s))}.
    \end{align*}
    This identity gives
    $$
      \vartheta'(s) = \frac{\sqrt{\mu}\kappa(s)^2}{2(\kappa(s)^2-\mu)},\qquad
      c'(s)
      = \frac{\mu\kappa'(s)}{\kappa(s)(\kappa(s)^2-\mu)}c(s)
      =  \frac{\mu\kappa'(s)}{\kappa(s)^2\sqrt{\kappa(s)^2-\mu}} 
    $$
    and thus the first claim follows from
    \begin{align*}
      \matII{W_1(s)}{W_2(s)}{W_1'(s)}{W_2'(s)}
      &=
      \matII{0}{c(s)}{-c(s)\vartheta'(s)}{c'(s)}
      \matII{\cos(\vartheta(s))}{\sin(\vartheta(s))}{-\sin(\vartheta(s))}{\cos(\vartheta(s))}.




    \end{align*}

Now we prove (i),(ii),(iii). For $l\in\mathbb{Z}$ we have
    \begin{align*}
       \vartheta(-s_*+ l\sqrt{2-k^2}K(k))-\vartheta(-s_*)
       &= \int_{-s_*}^{-s_*+l\sqrt{2-k^2}K(k)} \vartheta'(s) \,ds\\
       &= \int_{-s_*}^{-s_*+l\sqrt{2-k^2}K(k)} \frac{\sqrt{\mu}\kappa(s)^2}{2(\kappa(s)^2-\mu)} \,ds \\
       &= \int_0^{lK(k)}
       \frac{\sqrt{2-k^2}\sqrt{\mu}  \kappa(\sqrt{2-k^2}s-s_*)^2}{2(\kappa(\sqrt{2-k^2}s-s_*)^2-\mu)} \,ds
       \\
       &\stackrel{\eqref{eq:def_kappa_orbitlike}}{=}  \int_0^{lK(k)}
       \frac{\sqrt{1-k^2}\sqrt{2-k^2}\mathrm{dn}(s,k)^2}{(2-k^2)\mathrm{dn}(s,k)^2-1+k^2} \,ds   \\
       &=  \sqrt{1-k^2}\sqrt{2-k^2} \int_0^{lK(k)}
       \frac{\mathrm{dn}(s,k)^2}{(2-k^2)\mathrm{dn}(s,k)^2-1+k^2} \,ds   \\
       &= \frac{l}{2}\cdot 2\sqrt{2-k^2}\sqrt{1-k^2} \int_0^{K(k)}
       \frac{\mathrm{dn}(s,k)^2}{1-k^2(2-k^2)\mathrm{sn}(s,k)^2} \,ds.
     \end{align*}
     Here we used $\mathrm{dn}^2=1-k^2\mathrm{sn}^2$ and $\mathrm{dn}(2K(k)-s,k)=\mathrm{dn}(2K(k)+s,k)=\mathrm{dn}(s,k)$ in the last equation, 
     see~\eqref{eq:Jacobi_trigonometric_identities}.

The proof of (i) is finished once we have proved that 
     the second factor equals $\Delta\theta_k$. Using the formula 412.04 from \cite{ByrFri_handbook} for
     $\alpha:=k\sqrt{2-k^2}>k$ we get
     \begin{align*}
       &\;2\sqrt{2-k^2}\sqrt{1-k^2} \int_0^{K(k)}
       \frac{ \mathrm{dn}(s,k)^2}{1-k^2(2-k^2)\mathrm{sn}(s,k)^2} \,ds \\
       &= 2\sqrt{2-k^2}\sqrt{1-k^2} \Big(  K(k) +
       \frac{\pi   \sqrt{\alpha^2-k^2}
       (1-\Lambda_0(\arcsin(\sqrt{(1-\alpha^2)(k')^{-2}}),k))}{2\alpha\sqrt{1-\alpha^2}} \Big)  \\
       &= 2\sqrt{2-k^2}\sqrt{1-k^2} \Big(
       K(k) + \frac{\pi(1-\Lambda_0(\arcsin(k'),k)) }{2\sqrt{1-k^2}\sqrt{2-k^2}} \Big)  \\
       &\stackrel{\eqref{eq:def_rotation}}{=} \Delta\theta_k.
     \end{align*}

So (i) is proved  once we have shown $\vartheta(-s_*)=-\Delta\theta_k/2$. This identity, however, follows
     from $-2\pi<\vartheta(-s_*)\leq 0$ and 
     \begin{align*}
       e^{i\vartheta(-s_*)}
       \stackrel{\eqref{eq:def_theta}}{=} \frac{(W_2-iW_1)(-s_*)}{\sqrt{2-k^2}}
       \stackrel{\eqref{eq:def_Wj}}{=} (w_2-iw_1)(-K(k))
       = -i(w_1+iw_2)(-K(k))
       \stackrel{\ref{prop:w1w2_orbitlike}.(vii)}{=} e^{- i\Delta\theta_k /2}.
     \end{align*}

Finally, \eqref{eq:defn_w1w2_wavelike} shows
      that property (v) holds for the choice

      \begin{align*}
        \hat w_1(s)
        &:=  \frac{k(w_+(s) - w_-(s))}{w_+(0)+w_-(0)}
        =\frac{k(\Theta_1(s+\alpha_k,k)e^{-s\zeta(\alpha_k,k)}
        - \Theta_1(s-\alpha_k,k)e^{s\zeta(\alpha_k,k)}}{ 
        (w_+(0)+w_-(0))\Theta(s,k)}, \\
        \hat w_2(s)
        &:= \frac{k(w_+(s) + w_-(s))}{w_+(0)+w_-(0)}
        = \frac{k(\Theta_1(s+\alpha_k,k)e^{-s\zeta(\alpha_k,k)}
        + \Theta_1(s-\alpha_k,k)e^{s\zeta(\alpha_k,k)}}{ 
        (w_+(0)+w_-(0))\Theta(s,k)},
      \end{align*}
      since $\zeta(\alpha_k,k)>0$ and $\Theta_1(\cdot,k),\Theta(\cdot,k)$ are positive periodic functions.
      Notice that the all complex zeros of $\Theta_1,\Theta$ are known to be non-real, see 1051.07 in
      \cite{ByrFri_handbook}.

Differentiating both sides and using Proposition~\ref{prop:W1W2_wavelike}~(ii),(iii) we arrive at
    \begin{align*}
      &-c(s)\vartheta'(s) \vecII{\cosh(\vartheta(s))}{-\sinh(\vartheta(s))}
      + c'(s) \vecII{-\sinh(\vartheta(s))}{\cosh(\vartheta(s))} \;
      =\; \vecII{W_1'(s)}{W_2'(s)} \\
      &= \frac{\mu\kappa'(s)}{\kappa(s)(\kappa(s)^2-\mu)} \vecII{W_1(s)}{W_2(s)}
      - \frac{\sqrt{|\mu|}\kappa(s)^2}{2(\kappa(s)^2-\mu)} \vecII{W_2(s)}{W_1(s)}   \\
      &= \frac{\mu\kappa'(s)c(s)}{\kappa(s)(\kappa(s)^2-\mu)}
      \vecII{-\sinh(\vartheta(s))}{\cosh(\vartheta(s))} 
      - \frac{\sqrt{|\mu|}\kappa(s)^2c(s)}{2(\kappa(s)^2-\mu)}
      \vecII{\cosh(\vartheta(s))}{-\sinh(\vartheta(s))}.
    \end{align*}
    This identity gives
    $$
      \vartheta'(s) = \frac{\sqrt{|\mu|}\kappa(s)^2}{2(\kappa(s)^2-\mu)},\qquad
      c'(s)
      = \frac{\mu\kappa'(s)c(s)}{\kappa(s)(\kappa(s)^2-\mu)} 
      =  \frac{\mu\kappa'(s)}{\kappa(s)^2\sqrt{\kappa(s)^2-\mu}}
    $$
    and the claim follows from
    \begin{align*}
      \matII{W_1}{W_2}{W_1'}{W_2'}
      &= 
       \matII{0}{c}{-c\vartheta'}{c'}\matII{\cosh(\vartheta)}{
       -\sinh(\vartheta)}{-\sinh(\vartheta)}{\cosh(\vartheta)}.
    \end{align*}
